import { createHash } from 'node:crypto';
import { readFile } from 'node:fs/promises';

import {
    MOTION_PREVIEW_MAX_BYTES,
    MOTION_PREVIEW_MAX_DURATION_MS,
    MOTION_PREVIEW_MAX_HEIGHT,
    MOTION_PREVIEW_MAX_WIDTH
} from '../../models/motionPreview';
import { decodeMotionPreviewVideo } from './motionPreviewDecoder';

/** Rejects a clip that is not the one bounded, muted, progressive H.264 MP4 profile. */
export class InvalidMotionPreviewError extends Error {
    readonly statusCode = 400;
    readonly code = 'ADMIN_MOTION_PREVIEW_INVALID';

    constructor(message = 'The motion preview must be a short muted H.264 MP4 of at most 854×480.') {
        super(message);
        this.name = 'InvalidMotionPreviewError';
    }
}

type Box = { type: string; data: Buffer };

const invalid = () => new InvalidMotionPreviewError();

/** Splits a byte range into boxes, rejecting truncation, overlap, and unbounded box counts. */
const readBoxes = (buffer: Buffer, limit = 64): Box[] => {
    const result: Box[] = [];
    let offset = 0;
    while (offset < buffer.length) {
        if (result.length >= limit || buffer.length - offset < 8) throw invalid();
        let size = buffer.readUInt32BE(offset);
        let headerSize = 8;
        const type = buffer.toString('latin1', offset + 4, offset + 8);
        if (size === 1) {
            if (buffer.length - offset < 16) throw invalid();
            const large = buffer.readBigUInt64BE(offset + 8);
            if (large > BigInt(buffer.length - offset)) throw invalid();
            size = Number(large);
            headerSize = 16;
        } else if (size === 0) {
            size = buffer.length - offset;
        }
        if (size < headerSize || offset + size > buffer.length) throw invalid();
        result.push({ type, data: buffer.subarray(offset + headerSize, offset + size) });
        offset += size;
    }
    return result;
};

const only = (boxes: Box[], type: string) => {
    const matches = boxes.filter((box) => box.type === type);
    if (matches.length !== 1) throw invalid();
    return matches[0].data;
};

const allowOnly = (boxes: Box[], allowed: readonly string[]) => {
    if (boxes.some((box) => !allowed.includes(box.type))) throw invalid();
};

const compatibleBrands = new Set(['isom', 'iso2', 'iso4', 'iso5', 'iso6', 'mp41', 'mp42', 'avc1', 'M4V ']);

/** Container facts proven by the box walk; decoding is verified separately. */
export interface MotionPreviewContainer {
    durationMs: number;
    width: number;
    height: number;
}

/**
 * Walks the complete MP4 structure: a progressive (moov before mdat) file with exactly one track,
 * which is H.264 video, no sound, no fragments or protection, and bounded duration and size.
 */
export const inspectMotionPreviewContainer = (data: Buffer): MotionPreviewContainer => {
    const top = readBoxes(data, 16);
    allowOnly(top, ['ftyp', 'moov', 'mdat', 'free', 'skip', 'wide']);
    if (top[0]?.type !== 'ftyp' || top[0].data.length < 8) throw invalid();
    const brand = top[0].data.toString('latin1', 0, 4);
    if (!compatibleBrands.has(brand)) throw invalid();
    const moovIndex = top.findIndex((box) => box.type === 'moov');
    const mdatIndex = top.findIndex((box) => box.type === 'mdat');
    if (top.filter((box) => box.type === 'moov').length !== 1
        || top.filter((box) => box.type === 'mdat').length !== 1
        || moovIndex > mdatIndex
        || top[moovIndex].data.length > 1024 * 1024
        || top[mdatIndex].data.length === 0) throw invalid();

    const movie = readBoxes(top[moovIndex].data);
    allowOnly(movie, ['mvhd', 'trak', 'udta', 'meta', 'iods']);
    const header = only(movie, 'mvhd');
    const version = header[0];
    if (![0, 1].includes(version) || header.length < (version === 0 ? 20 : 32)) throw invalid();
    const timescale = header.readUInt32BE(version === 0 ? 12 : 20);
    const duration = version === 0 ? header.readUInt32BE(16) : Number(header.readBigUInt64BE(24));
    if (!timescale || !duration || !Number.isSafeInteger(duration)) throw invalid();
    const durationMs = Math.round((duration * 1000) / timescale);
    if (durationMs <= 0 || durationMs > MOTION_PREVIEW_MAX_DURATION_MS) throw invalid();

    const track = readBoxes(only(movie, 'trak'));
    allowOnly(track, ['tkhd', 'mdia', 'edts', 'udta', 'meta']);
    const trackHeader = only(track, 'tkhd');
    const trackVersion = trackHeader[0];
    if (![0, 1].includes(trackVersion) || trackHeader.length < (trackVersion === 0 ? 84 : 96)) throw invalid();
    const width = trackHeader.readUInt32BE(trackVersion === 0 ? 76 : 88) / 65536;
    const height = trackHeader.readUInt32BE(trackVersion === 0 ? 80 : 92) / 65536;
    const longer = Math.max(width, height);
    const shorter = Math.min(width, height);
    if (!(shorter > 0) || longer > MOTION_PREVIEW_MAX_WIDTH || shorter > MOTION_PREVIEW_MAX_HEIGHT) throw invalid();

    const media = readBoxes(only(track, 'mdia'));
    const handler = only(media, 'hdlr');
    if (handler.length < 12 || handler.toString('latin1', 8, 12) !== 'vide') throw invalid();
    const sampleTable = readBoxes(only(readBoxes(only(media, 'minf')), 'stbl'));
    const descriptions = only(sampleTable, 'stsd');
    if (descriptions.length < 16 || descriptions.readUInt32BE(4) !== 1) throw invalid();
    const codec = descriptions.toString('latin1', 12, 16);
    if (codec !== 'avc1' && codec !== 'avc3') throw invalid();

    return { durationMs, width: Math.round(width), height: Math.round(height) };
};

/** Facts recorded for an accepted preview. */
export interface ValidatedMotionPreview extends MotionPreviewContainer {
    byteLength: number;
    sha256: string;
}

export interface MotionPreviewValidationDependencies {
    readBytes: (file: Pick<Express.Multer.File, 'path' | 'buffer'>) => Promise<Buffer>;
    decode: typeof decodeMotionPreviewVideo;
}

const defaultValidationDependencies: MotionPreviewValidationDependencies = {
    readBytes: async (file) => (file.path ? readFile(file.path) : Buffer.from(file.buffer ?? [])),
    decode: decodeMotionPreviewVideo
};

/**
 * Validates the actual bytes, never the multipart name or MIME alone: size, the strict container
 * walk, then a bounded full decode of the one video stream.
 */
export const validateMotionPreviewFile = async (
    file: Pick<Express.Multer.File, 'size' | 'path' | 'buffer' | 'mimetype'>,
    signal?: AbortSignal,
    dependencies: Partial<MotionPreviewValidationDependencies> = {}
): Promise<ValidatedMotionPreview> => {
    const { readBytes, decode } = { ...defaultValidationDependencies, ...dependencies };
    if (!Number.isSafeInteger(file.size) || file.size <= 0 || file.size > MOTION_PREVIEW_MAX_BYTES) throw invalid();
    if (String(file.mimetype ?? '').toLowerCase() !== 'video/mp4') throw invalid();
    const data = await readBytes(file);
    if (data.length !== file.size) throw invalid();
    const container = inspectMotionPreviewContainer(data);
    await decode(file, container.durationMs, signal);
    return {
        ...container,
        byteLength: data.length,
        sha256: createHash('sha256').update(data).digest('hex')
    };
};
